 static final class Idle extends Process {boolean alive=true;int reads;public OutputStream getOutputStream(){return new ByteArrayOutputStream();}public InputStream getErrorStream(){return new ByteArrayInputStream(new byte[0]);}public InputStream getInputStream(){return new InputStream(){public int read(){reads++;throw new AssertionError("blocking read");}public int available(){return 0;}};}public int waitFor(){return 0;}public int exitValue(){if(alive)throw new IllegalThreadStateException();return 0;}public boolean isAlive(){return alive;}public void destroy(){alive=false;}}
